<script lang="ts">
  import NavMain, { type NavItem } from "$lib/layout/nav-main.svelte";
  import NavBottom, { type NavBottomItem } from "$lib/layout/nav-bottom.svelte";
  import * as Sidebar from "$lib/components/ui/sidebar";
  import type { ComponentProps } from "svelte";
  import SveltePortal from "$lib/blocks/svelte-utils/portal/SveltePortal.svelte";
  import { queryState } from "$lib/database/nodeRepository.svelte";
  import { evolu } from "$lib/database/evolu/evolu_instance";
  import { getNodesQuery } from "$lib/database/evolu/queries";
  import { convertDbNodeToDynamicLayoutNode } from "$lib/database/layoutDbNodeConverter";
  import { openAddNewDashboardDialog, openEditNodeDialog } from "$lib/state/app-state.svelte";
  import { page } from "$app/state";
  import { Newspaper } from "@lucide/svelte";

  let {
    ref = $bindable(null),
    collapsible = "icon",
    ...restProps
  }: ComponentProps<typeof Sidebar.Root> = $props();

  const allDashboards = queryState(() => getNodesQuery({
    type: "dashboard"
  }), evolu, {
    useLoadQueryResult: true
  });

  let navItems = $derived.by(() => {
    return allDashboards.rows.map((row) => {
      const mapped = convertDbNodeToDynamicLayoutNode(row);


      return {
        id: mapped.id,
        title: mapped.layoutData.label ?? "Untitled",
        iconName: mapped.nodeConfig.icon,
        isActive: page.params.slug === mapped.id,
        node: mapped,
        menuItems: [
          {
            id: "config",
            title: "Configuration"
          },
          {
            id: "delete",
            title: "Delete"
          }
        ],
        selectedBackgroundColor: mapped.nodeConfig.selectedBackgroundColor,
        iconColor: mapped.nodeConfig.iconColor
      };
    }).toSorted((a, b) => (a.node?.order ?? 0) - (b.node?.order ?? 0));
  });

  let navBottomItems = [
    {
      title: "Changelog",
      url: "/changelog",
      icon: Newspaper,
      isActive: false
    },
    {
      divider: true
    },
    {
      title: "Settings",
      url: "/settings",
      icon: Settings2,
      isActive: false
    }
  ] satisfies NavBottomItem[];

  function onNewDashboard () {
    openAddNewDashboardDialog();
  }

  function itemClicked (item: NavItem) {
    console.log(item);
  }

  function menuItemClicked (item: NavItem, menuItemId: string) {
    if (menuItemId === "config") {
      openEditNodeDialog({
        node: item.node
      });
    }

    console.log(item, menuItemId);
  }
</script>

<Sidebar.Root collapsible="icon" style="--sidebar-width-icon: 3.5rem">
